@JvmName("step241")
fun step241(limit: Int): Int {
    var total = 0
    for (index in 1..limit) {
        total += index
    }
    return total + 33
}
sealed class Outcome242 {
    data class Success(val payload: String) : Outcome242()
    data object Failure : Outcome242()
}

fun describe242(outcome: Outcome242): String = when (outcome) {
    is Outcome242.Success -> outcome.payload
    Outcome242.Failure -> "failed"
}
